package org.transittr;
import java.io.*;import java.security.KeyStore;import java.security.cert.*;import java.util.*;import javax.net.ssl.*;
/** Platform trust plus explicitly bundled CA roots. Never trusts a server-supplied root implicitly. */
public final class TlsSecurity {
 private static X509TrustManager system,extra;private static SSLSocketFactory factory;
 private static X509TrustManager manager(KeyStore store)throws Exception{TrustManagerFactory f=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());f.init(store);for(TrustManager m:f.getTrustManagers())if(m instanceof X509TrustManager)return (X509TrustManager)m;throw new CertificateException("Güven deposu bulunamadı");}
 public static synchronized void init(android.content.Context context){try{system=manager(null);KeyStore roots=KeyStore.getInstance(KeyStore.getDefaultType());roots.load(null,null);CertificateFactory f=CertificateFactory.getInstance("X.509");int count=0;for(String name:context.getAssets().list("trust-roots")){if(!name.endsWith(".pem"))continue;InputStream in=context.getAssets().open("trust-roots/"+name);try{for(java.security.cert.Certificate c:f.generateCertificates(in))roots.setCertificateEntry("root-"+(count++),c);}catch(CertificateException unsupported){android.util.Log.w("TransitTR","Unsupported bundled CA root: "+name);}finally{in.close();}}if(count>0)extra=manager(roots);}catch(Exception e){extra=null;}}
 private static synchronized void trust(X509Certificate[] chain)throws CertificateException{if(chain==null||chain.length==0)throw new CertificateException("Sunucu sertifikası eksik");for(X509Certificate c:chain)c.checkValidity();try{if(system==null)system=manager(null);system.checkServerTrusted(chain,chain[0].getPublicKey().getAlgorithm());return;}catch(Exception primary){if(extra!=null)try{extra.checkServerTrusted(chain,chain[0].getPublicKey().getAlgorithm());return;}catch(CertificateException ignored){}throw new CertificateException("Sunucu sertifika zinciri doğrulanamadı");}}
 static boolean dnsMatch(String host,String pattern){host=host.toLowerCase(Locale.US);pattern=pattern.toLowerCase(Locale.US);if(!host.matches("[a-z0-9.-]+")||host.endsWith(".")||pattern.endsWith("."))return false;if(pattern.indexOf('*')<0)return host.equals(pattern);if(!pattern.startsWith("*.")||pattern.indexOf('*',1)>=0)return false;String suffix=pattern.substring(2);if(suffix.indexOf('.')<0||!host.endsWith("."+suffix))return false;String label=host.substring(0,host.length()-suffix.length()-1);return label.length()>0&&label.indexOf('.')<0;}
 static void hostname(String host,X509Certificate leaf)throws CertificateException{Collection<List<?>> names=leaf.getSubjectAlternativeNames();if(names!=null)for(List<?> name:names)if(name.size()>1&&Integer.valueOf(2).equals(name.get(0))&&name.get(1) instanceof String&&dnsMatch(host,(String)name.get(1)))return;throw new CertificateException("Sunucu adı sertifikayla eşleşmiyor");}
 public static void verify(String host,X509Certificate[] chain)throws CertificateException{trust(chain);hostname(host,chain[0]);}
 public static synchronized void configure()throws Exception{if(factory==null){X509TrustManager checked=new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException("İstemci doğrulaması desteklenmiyor");}public void checkServerTrusted(X509Certificate[] c,String a)throws CertificateException{trust(c);}};SSLContext c=SSLContext.getInstance("TLS");c.init(null,new TrustManager[]{checked},null);factory=c.getSocketFactory();HttpsURLConnection.setDefaultSSLSocketFactory(factory);}}
}
